    'c.cv': 'یک سی‌وی کوتاه', // nieuw, nalezen // nagelezen AI 22 nov
    'c.cv.b': 'اینجا سی‌وی کوتاه است: ۱ یا ۲ صفحه. معلومات تماس، تجربهٔ کاری، تحصیلات، زبان‌ها و مهارت‌های خود را بنویسید. عکس لازم نیست. لازم نیست دین، سن یا حالت مدنی (متأهل یا مجرد) خود را بنویسید. دربارهٔ کارهایی که کرده می‌توانید راست بگویید. از کسی بخواهید که هالندی شما را کنترول کند.', // nieuw, nalezen // nagelezen AI 22 nov
    'c.cv.p': 'سی‌وی مرا می‌خوانید؟ هالندی من درست است؟',
    'c.cv.s': 'شما ۳ سال در کشور خود در یک فابریکه کار کرده‌اید، اما دیپلوم ندارید. در سی‌وی خود چه می‌نویسید؟',
    'c.cv.o1': 'آن کار و کارهایی را که آنجا کردید، به راستی بنویسید.',
