    'c.translate': 'اپ‌های ترجمه: هوشمند، اما کنترول کنید',
    'c.translate.b': 'یک اپ ترجمه، مثل Google Translate، خیلی کمک می‌کند. شما می‌توانید تایپ کنید، گپ بزنید، یا از حالت گفتگو استفاده کنید تا با یک همکار صحبت کنید. با کمره می‌توانید تخته‌ها، یادداشت‌ها و رهنمایی‌ها را ترجمه کنید. در بسیاری از تیلفون‌ها، WhatsApp هم می‌تواند پیام‌ها را ترجمه کند. از تیلفون خود فقط در جایی استفاده کنید که مصئون و اجازه باشد. هرگز نزدیک ماشین‌ها یا فورک‌لیفت‌ها از آن استفاده نکنید. همیشه اول بپرسید. اپ‌ها اشتباه می‌کنند. برای چیزهای مهم، مثل قرارداد شما، یک نامه یا یک رهنمایی مصئونیت، از یک شخص هم بخواهید که آن را توضیح بدهد. بدون اجازه از کاغذهای محرم کار عکس نگیرید.',
    'c.translate.p': 'برای ترجمه از تیلفون خود استفاده کرده می‌توانم؟',
    'c.translate.s': 'سرپرست شما رهنمایی‌های مصئونیت به هالندی به شما می‌دهد. شما فقط چند کلمه را می‌فهمید. چه می‌کنید؟', // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.translate.o1': 'توضیح بخواهید، و بپرسید که آیا استفاده از اپ مشکل ندارد.', // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.translate.o2': '«ja, ja» بگویید و کار را شروع کنید.', // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.translate.o3': 'از آن عکس بگیرید و به دوستان خود بفرستید تا آن را ترجمه کنند.', // nieuw, nalezen (AI-correctie 2 nov 2026) // nagelezen AI 22 nov
    'c.translate.w': 'اپ ترجمه کمک می‌کند که زود بفهمید، اما شاید اشتباه کند. برای مصئونیت، توضیح یک شخص بهترین کنترول است. کاغذهای کار شاید محرم باشند، پس بدون اجازه آن‌ها را با کسی شریک نسازید.',
    'c.understood': 'کنترول کنید که درست فهمیده‌اید',
    'c.understood.b': 'تیلفون شما می‌تواند گپ را به متن تبدیل کند (زیرنویس زنده): Live Transcribe در Android، و Live Captions در iPhone. ببینید که تیلفون شما کدام زبان‌ها را پشتیبانی می‌کند. همچنان می‌توانید از کسی بخواهید که آن را بنویسد، نشان بدهد، یا آهسته گپ بزند. بپرسید که آیا یک رهنمایی با تصویر، یا به زبان شما، هست. بعد آنچه را فهمیدید دوباره بگویید: «Dus ik moet eerst …?» (پس اول باید …؟). این کار اینجا عادی است، و جلوی اشتباه را می‌گیرد.',
    'c.understood.p': 'پس اول باید قطی‌ها را بشمارم؟',
    'c.understood.s': 'یک همکار توضیح می‌دهد که یک ماشین نو چطور کار می‌کند. او تیز گپ می‌زند و شما چند کلمه را نمی‌فهمید. چه می‌کنید؟',
    'c.understood.o1': 'از او بخواهید که نشان بدهد یا بنویسد، بعد آن را دوباره بگویید.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.understood.o2': 'سر خود را به معنای بلی تکان بدهید و «ja, ja» بگویید، تا وقت او ضایع نشود.',
    'c.understood.o3': 'بعداً تنها ماشین را امتحان کنید و ببینید که چه می‌شود.',
    'c.understood.w': 'نشان دادن، نوشتن و دوباره گفتن، کنترول‌های زود هستند. همکار شما می‌تواند پیش از اینکه کار غلط شود، اشتباه شما را درست کند. اینجا این کار احتیاط حساب می‌شود، نه کندی.',
    'c.keeplearning': 'به آموختن ادامه بدهید، هر روز کمی',
    'c.keeplearning.b': 'هر روز چند دقیقه بیشتر از یک ساعت طولانی در هفته کمک می‌کند. کلمه‌های نو از کار را در یک اپ یادداشت در تیلفون خود ذخیره کنید. به هالندی ساده گوش بدهید، مثلاً NOS Jeugdjournaal (اخبار برای اطفال) یا یک پادکاست به هالندی آهسته. بسیاری از کتابخانه‌های عامه یک Taalhuis دارند: کمک مفت برای هالندی، اکثراً با یک taalcafé (جایی برای تمرین گپ زدن) یا یک همراه زبان (taalmaatje). همکاران اکثراً زبان را به انگلیسی تبدیل می‌کنند تا به شما کمک کنند. با مهربانی از آن‌ها بخواهید که با شما هالندی گپ بزنند: بیشتر مردم کمک کردن را خوش دارند.',
    'c.keeplearning.p': 'فقط با من هالندی گپ بزنید، این طور آن را زودتر یاد می‌گیرم.',
    'c.keeplearning.s': 'همکاران شما وقتی با شما گپ می‌زنند، همیشه زبان را به انگلیسی تبدیل می‌کنند. شما می‌خواهید هالندی یاد بگیرید. چه می‌کنید؟',
    'c.keeplearning.o1': 'از آن‌ها تشکر کنید، و بخواهید که با شما هالندی گپ بزنند.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.keeplearning.o2': 'چیزی نگویید. هالندی خودش می‌آید.',
    'c.keeplearning.o3': 'شما هم انگلیسی جواب بدهید، چون این مؤدبانه‌تر است.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.keeplearning.w': 'همکاران اکثراً از روی مهربانی زبان را به انگلیسی تبدیل می‌کنند. وقتی هالندی بخواهید، بیشتر شان با خوشی کمک می‌کنند. هر روز کمی گپ زدن در کار، یکی از تیزترین راه‌های آموختن است.',
