    's.boundaries.2': "این حرف به نظرم خنده‌دار نیست.",
    's.boundaries.3': "می‌خواهم چیزی را به مشاور معتمد گزارش بدهم.",
    'c.boundaries.q': "این‌قدر سخت‌گیر نباش، فقط یک شوخی بود.",
    'c.boundaries.a': "برای من نی. می‌خواهم بس کنید.", // nagelezen AI ronde 3
    'c.gossip': "غیبت و شبکه‌های اجتماعی",
    'c.gossip.b': "گپ زدن پشت سر یک همکار (roddelen) به اعتماد در تیم ضرر می‌رساند. با کسی مشکل دارید؟ با خود آن شخص گپ بزنید، یا با سرپرست خود. در انترنت همان قانون‌های کار اعتبار دارد. بدون اجازه هیچ چیزی دربارهٔ همکاران، مشتریان یا کمپنی پست نکنید. این شامل عکس، ویدیو و پیام هم می‌شود. آمر شما می‌تواند ببیند که شما چه پست می‌کنید، و آن می‌تواند سال‌ها آنلاین بماند. خیلی تیم‌ها یک گروپ چت (groepsapp) برای کار دارند: آن را فقط برای کار استفاده کنید، و اسکرین‌شات آن را با دیگران شریک نسازید. شریک ساختن چیزهای شخصی یک همکار یا مسخره کردن کسی در انترنت هم آزار و اذیت (pesten) است.",
    'c.gossip.p': "نمی‌خواهم این آنلاین باشد.",
    'c.gossip.s': "وقتی روی زمین تر می‌لغزید، یک همکار از شما فلم می‌گیرد. او می‌خواهد ویدیو را در TikTok بگذارد. چه می‌کنید؟",
    'c.gossip.o1': 'بگویید «Nee, dat wil ik niet» و از او بخواهید که آن را پاک کند.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.gossip.o2': "بخندید و بگذارید پست کند، تا سخت‌گیر معلوم نشوید.",
    'c.gossip.o3': 'از او بخواهید که آن را بدون نام شما پست کند.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.gossip.w': 'معمولاً هیچ کس بدون اجازهٔ شما نمی‌تواند ویدیوی شما را آنلاین بگذارد. «نی» گفتن عادی است، و کارفرمای شما باید کاری کند وقتی همکاران در انترنت یکدیگر را مسخره می‌کنند. اگر باز هم آن را پست کرد، به سرپرست خود بگویید.', // nieuw, nalezen // nagelezen AI 22 nov
    'c.boundaries': "از حد گذشتن",
    'c.boundaries.b': "Grensoverschrijdend gedrag رفتاری است که از حد کسی می‌گذرد. مثلاً: دست زدن ناخواسته، حرف‌ها یا شوخی‌های جنسی، خیره نگاه کردن، عکس‌های ناخواسته، تهدید یا چیغ زدن. مهم نیست که شخص دیگر «آن را به شوخی گفته بود»: مهم این است که شما چه حس می‌کنید. اگر می‌توانید، روشن بگویید که می‌خواهید بس شود. بنویسید که چه شد، چه وقت، و کی آن را دید. به سرپرست خود، مشاور معتمد (vertrouwenspersoon، اگر وجود داشته باشد) یا HR بگویید. کارفرمای شما باید از شما محافظت کند، و نباید شما را به خاطر گزارش دادن جزا بدهند. دیدید که این برای یک همکار اتفاق افتاد؟ بپرسید که خوب است یا نی، و پیشنهاد کنید که شاهد باشید.",
    'c.boundaries.p': "می‌خواهم بس کنید.", // nagelezen AI ronde 3 // nagelezen AI 22 nov
    'c.boundaries.s': "رییس تیم شما اکثراً دست خود را بالای پشت شما می‌گذارد و می‌گوید که شما «زیبا» معلوم می‌شوید. این شما را ناراحت می‌کند. او نوبت‌های کاری شما را تعیین می‌کند. چه می‌کنید؟",
    'c.boundaries.o1': 'بنویسید که چه اتفاق می‌افتد و به vertrouwenspersoon بگویید.', // nagelezen (2e lezing) // nagelezen AI 22 nov
    'c.boundaries.o2': "چیزی نگویید، چون او نوبت‌های کاری شما را تعیین می‌کند.",
    'c.boundaries.o3': "کار خود را بدون گفتن دلیل به کسی ترک کنید.",
    'c.boundaries.w': 'این رفتار ناخواسته است، و تقصیر شما نیست. مشاور معتمد به طور محرمانه به شما گوش می‌دهد و کمک می‌کند که قدم بعدی را انتخاب کنید. وقتی آن را گزارش می‌دهید، از شما محافظت می‌شود. می‌توانید با HR هم گپ بزنید.', // nagelezen (2e lezing) // nagelezen AI 22 nov
