    'c.shelves.b': 'وقتی رف‌ها را پر می‌کنید، به تاریخ روی جنس‌ها نگاه کنید. جنس‌هایی را که تاریخ شان نزدیک‌تر است در پیش‌رو بگذارید، و جنس‌های نو را در عقب. مشتری‌ها از پیش‌رو برمی‌دارند، پس جنس‌های کهنه زودتر فروخته می‌شوند. آیا تاریخ یک جنس گذشته، یا خراب شده است؟ آن را از رف بردارید و بپرسید که با آن چه کنید. راهروها را از قطی‌ها و کراچی‌ها خالی نگه دارید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.',
