    'c.checkout.b': 'شما اجازه ندارید به کسی که کمتر از ۱۸ سال عمر دارد الکول یا تنباکو بفروشید: این قانون است. مطمئن نیستید که مشتری چند ساله است؟ کارت هویتش را بخواهید. بسیاری از دکان‌ها از هر کسی که جوان‌تر از ۲۵ سال معلوم می‌شود کارت هویت می‌خواهند. کارت هویت ندارد، یا کمتر از ۱۸ سال است؟ پس به او نفروشید، و با ادب باشید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.',
