    'c.measures': 'هوشیارانه بشمارید، اندازه کنید، حدس نزنید',
    'c.measures.b': 'قطی‌های زیاد را باید بشمارید؟ قطی‌های یک طبقه را بشمارید، و تعداد طبقه‌ها را. بعد ضرب کنید: ۸ قطی در یک طبقه و ۵ طبقه می‌شود ۴۰ قطی. برای مواد پاک‌کاری، همان مقداری را که روی لیبل نوشته شده اندازه کنید. زیادتر بهتر نیست: به پوست شما ضرر رسانده می‌تواند و پول ضایع می‌شود. از یک عدد مطمئن نیستید؟ دوباره بشمارید، یا بپرسید. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.',
