    'c.aihelp.b': 'اپ‌های هوش مصنوعی و چت‌بات‌ها، مانند ChatGPT، می‌توانند ترجمه کنند، یک نامه را توضیح بدهند یا در نوشتن پیام به شما کمک کنند. این مفید است. اما هوش مصنوعی گاهی اشتباه می‌کند و باز هم خیلی مطمئن معلوم می‌شود. موضوع دربارهٔ قرارداد، معاش، دوا یا مصئونیت است؟ پس همیشه جواب را با یک انسان کنترول کنید. مثلاً با سرپرست خود، بخش منابع بشری (HR) یا Juridisch Loket.',
