    's.healthy.1': "امروز خیلی مانده هستم.", // nieuw, nalezen // nagelezen AI 22 nov
    's.healthy.2': "همیشه اول نان صبح می‌خورم.", // nieuw, nalezen // nagelezen AI 22 nov
