    's.road.2': "سرک لغزنده است. آهسته موتر می‌رانم.", // nieuw, nalezen
    's.road.3': "کی مسیر و وقت‌های کار مرا تعیین می‌کند؟", // nieuw, nalezen
    'c.road.q': "امروز می‌توانید یک دور دیگر هم بروید؟", // nieuw, nalezen
    'c.road.a': "نی، آن وقت برای تفریح خود وقت ندارم.", // nieuw, nalezen
    'c.parcel': "کسی در خانه نیست، یا بسته خراب است", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.b': "مشتری در خانه نیست؟ مطابق مقررات کمپنی خود عمل کنید: پیش همسایه‌ها بروید، یا بسته را پس ببرید. آن را همین طور پیش دروازه نگذارید، مگر اینکه مشتری این را خواسته باشد. یک بسته خراب یا تر است؟ آن را طوری نرسانید که گویا هیچ مشکلی نیست. به حیث ثبوت یک عکس بگیرید، و آن را در سکنر یا اپ گزارش بدهید. صادق بودن دربارهٔ یک مشکل همیشه از پنهان کردن آن بهتر است. مقررات در هر کمپنی فرق می‌کند: از سرپرست خود بپرسید که مقررات جای کار شما چیست.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.p': "این بسته خراب است. این هم یک عکس.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.s': "مشتری در خانه نیست، همسایه‌ها هم نیستند. چه می‌کنید؟", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.o1': "«در خانه نیست» را سکن کنید و بسته را پس ببرید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.o2': "آن را «رسانده شد» سکن کنید و پیش دروازه بگذارید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.o3': "آن را پشت سطل کثافات پنهان کنید تا کسی آن را نبیند.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.parcel.w': "بسته‌ای که «رسانده شد» سکن شده، باید واقعاً پیش مشتری باشد. وقتی چیزی را که واقعاً پیش آمده سکن کنید، مشتری می‌تواند بسته را بعداً بگیرد، و هیچ کس فکر نمی‌کند که شما آن را گم کرده‌اید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road': "مصئون در سرک، و کار عادلانه", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.b': "هیچ وقت در وقت موتر راندن تیلفون را در دست نگیرید: این منع است. برای مسیریابی از یک پایهٔ تیلفون استفاده کنید. وقت‌های تفریح خود را بگیرید، حتی در یک روز پرکار. یک بستهٔ سنگین؟ از کراچی دستی استفاده کنید، یا آن را با هم بلند کنید. یخ یا برف؟ آهسته برانید: ناوقت رسیدن از حادثه بهتر است. بعضی کمپنی‌ها می‌گویند که شما به حیث کارگر آزاد (zelfstandig) کار می‌کنید. اما کی ساعت‌های کار، مسیر و لباس شما را تعیین می‌کند؟ اگر کمپنی همهٔ این‌ها را تعیین کند، شاید در اصل معاش‌بگیر (in loondienst) باشید. آن وقت اکثراً حقوق بیشتری دارید، مثل معاش در وقت مریضی. بیشتر دربارهٔ این در درس «اسناد، ادغام و کار شما». معلومات عمومی. برای وضعیت خود تان: از اتحادیهٔ کارگری، Juridisch Loket یا FairWork بپرسید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.p': "حالا وقت تفریح خود را می‌گیرم. بعد به راه خود ادامه می‌دهم.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.s': "کمپنی شما را کارگر آزاد می‌گوید. اما ساعت‌های کار، مسیر و لباس شما را خودش تعیین می‌کند. چه می‌کنید؟", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.o1': "مشوره بگیرید: شاید شما معاش‌بگیر باشید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.o2': "هیچ کاری نکنید: در قرارداد نوشته کارگر آزاد، پس همین است.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.o3': "ساعت‌های بیشتر کار کنید تا همان اندازه پول پیدا کنید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.road.w': "مهم این است که شما واقعاً چطور کار می‌کنید، نه فقط کلمه‌ای که در قرارداد است. اگر کمپنی تعیین کند که چطور، چه وقت و کجا کار کنید، اکثراً معاش‌بگیر هستید. آن وقت حقوق بیشتری دارید.", // nieuw, nalezen // nagelezen AI 22 nov
    'l.feelwell': "احساس خوب در کار", // nieuw, nalezen // nagelezen AI 22 nov
    'w.werkdruk': "فشار کار (کار زیاد در وقت کم)", // nieuw, nalezen // nagelezen AI 22 nov
