    'w.ploegendienst': "کار نوبتی (نوبت صبح، بعد از ظهر و شب، یکی پس از دیگری)", // nieuw, nalezen // nagelezen AI 22 nov
    'w.heimwee': "دلتنگی برای وطن (دل تان برای خانه تنگ شده)", // nieuw, nalezen // nagelezen AI 22 nov
    'w.familie': "فامیل", // nieuw, nalezen // nagelezen AI 22 nov
    'w.alleen': "تنها", // nieuw, nalezen // nagelezen AI 22 nov
    's.feelwell.1': "به خاطر کار نوبتی بد خواب می‌کنم.", // nieuw, nalezen // nagelezen AI 22 nov
    's.feelwell.2': "خیلی زیاد است. به تنهایی از عهدهٔ آن برآمده نمی‌توانم.", // nieuw, nalezen // nagelezen AI 22 nov
    's.feelwell.3': "دلم برای وطن تنگ شده. فامیلم دور است.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.feelwell.q': "حال تان خوب است؟", // nieuw, nalezen // nagelezen AI 22 nov
    'c.feelwell.a': "زیاد خوب نی. اکثراً شب‌ها بیدار می‌مانم.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.feelwell': "خیلی زیاد است؟ لازم نیست به تنهایی از عهدهٔ آن برآیید", // nieuw, nalezen // nagelezen AI 22 nov
    'c.feelwell.b': "همه گاهی مانده، تحت فشار یا غمگین می‌شوند. کار خیلی زیاد (werkdruk)، خواب بد به خاطر کار نوبتی یا دلتنگی برای فامیل می‌تواند همه چیز را سنگین کند. لازم نیست این بار را به تنهایی بردارید، و گفتن «خیلی زیاد است» ضعف نیست. با کسی که به او اعتماد دارید گپ بزنید. مثلاً سرپرست خود، داکتر کمپنی (bedrijfsarts) یا داکتر خانوادگی خود (huisarts). یا مشاور معتمد (vertrouwenspersoon)، اگر کمپنی شما چنین کسی دارد. خود تان هم می‌توانید برای گپ زدن با داکتر کمپنی وقت بخواهید. داکترها به آمر شما نمی‌گویند که شما چه گفته‌اید. به خودکشی فکر می‌کنید، یا نگران کسی هستید؟ به ۱۱۳ زنگ بزنید (مفت، شب و روز)، یا در 113.nl چت کنید.", // nagelezen AI 22 nov
    'c.feelwell.p': "حالم زیاد خوب نیست. می‌توانم یک لحظه با شما گپ بزنم؟", // nieuw, nalezen // nagelezen AI 22 nov
    'c.feelwell.s': "چند هفته است که بد خواب می‌کنید و کار خیلی زیاد است. خیلی مانده هستید. چه می‌کنید؟", // nieuw, nalezen // nagelezen AI 22 nov
    'c.feelwell.o1': "به سرپرست خود یا داکتر کمپنی بگویید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.feelwell.o2': "چیزی نگویید و سخت‌تر و تیزتر کار کنید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.feelwell.o3': "در خانه بمانید و به هیچ کس نگویید چرا.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.feelwell.w': "زود گفتن آن ضعف نیست. آن وقت می‌توانید با هم راه حلی پیدا کنید، مثلاً نوبت‌های کاری دیگر. لازم نیست به تنهایی از عهدهٔ آن برآیید.", // nieuw, nalezen // nagelezen AI 22 nov
