    'w.lichtwerk': "کار سبک (نه سنگین)", // nieuw, nalezen // nagelezen AI 22 nov
    'w.zwaarwerk': "کار سنگین", // nieuw, nalezen // nagelezen AI 22 nov
    'w.herstellen': "صحت یافتن، دوباره جور شدن", // nieuw, nalezen // nagelezen AI 22 nov
    'w.welkomterug': "دوباره خوش آمدید", // nieuw, nalezen // nagelezen AI 22 nov
    's.backtowork.1': "با نیم روز شروع می‌کنم.", // nieuw, nalezen // nagelezen AI 22 nov
    's.backtowork.2': "کار سبک را حالا کرده می‌توانم. کار سنگین هنوز نی.", // nieuw, nalezen // nagelezen AI 22 nov
    's.backtowork.3': "داکتر کمپنی می‌گوید: آهسته آهسته زیاد کنید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.q': "دوباره خوش آمدید! حال تان بهتر است؟", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.a': "بلی، بهتر شده‌ام. آهسته آهسته پیش می‌روم.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork': "برگشتن قدم به قدم", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.b': "جور شده‌اید؟ به کارفرما خبر بدهید که دوباره کار کرده می‌توانید (betermelden). بعد از یک مریضی درازتر، اکثراً قدم به قدم شروع می‌کنید: اول ساعت‌های کمتر، یا کار سبک‌تر. داکتر کمپنی (bedrijfsarts) دربارهٔ کارهایی که کرده می‌توانید مشوره می‌دهد. مدت درازتری مریض بوده‌اید؟ آن وقت شما و کارفرما با هم برای برگشت شما یک پلان می‌سازید. این قانون است (Wet verbetering poortwachter). واضح بگویید که چه کاری کرده می‌توانید، و چه کاری هنوز نی. لازم نیست به همکاران بگویید که چه مریضی داشتید. معلومات عمومی. برای وضعیت خود تان: از کارفرما، اتحادیهٔ کارگری یا Juridisch Loket بپرسید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.p': "این را حالا کرده می‌توانم. آن را هنوز کرده نمی‌توانم.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.s': "شما سه هفته مریض بودید. در روز اول برگشت، سرپرست شما از شما می‌خواهد که قطی‌های سنگین را بلند کنید. داکتر کمپنی گفته: فعلاً فقط کار سبک. چه می‌کنید؟", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.o1': "آرام بگویید که حالا کار سبک کرده می‌توانید، و چه کاری را هنوز کرده نمی‌توانید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.o2': "با این هم قطی‌ها را بلند کنید: نمی‌خواهید مشکل‌ساز باشید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.o3': "بدون یک کلمه به خانه بروید.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.backtowork.w': "سرپرست شما می‌خواهد که برگردید، آن هم صحتمند. وقتی واضح بگویید که چه کرده می‌توانید، او می‌تواند کار را پلان کند. خیلی زود کار زیاد کردن می‌تواند شما را دوباره مریض کند.", // nieuw, nalezen // nagelezen AI 22 nov
