    'c.drawing.w': "پرزه‌ای که به زور داخل شود می‌تواند بعداً بشکند، پیش مشتری. وقتی خبر بدهید، علت آن پیدا می‌شود.", // nieuw, nalezen // nagelezen AI 22 nov
