    's.size.1': "مساحت، درازی ضرب بر است.", // nieuw, nalezen
    's.size.2': "حجم، درازی ضرب بر ضرب بلندی است.", // nieuw, nalezen
    's.size.3': "ده ملی‌متر یک سانتی‌متر است.", // nieuw, nalezen
    'c.size.q': "فرش چند متر مربع است؟", // nieuw, nalezen
