    'c.wood.w': "دراز را دوباره اره کرده می‌توانید، کوتاه را جور کرده نمی‌توانید. دوباره اندازه کردن یک دقیقه وقت می‌گیرد؛ یک تختهٔ نو خیلی بیشتر.", // nieuw, nalezen // nagelezen AI 22 nov
