    'c.hedge.s': "شما در ماه می یک پرچین را قیچی می‌کنید. یک آشیانه با چوچه‌ها می‌بینید. چه می‌کنید؟", // nieuw, nalezen
    'c.hedge.o1': "همانجا بس کنید، و به سرپرست خود بگویید.", // nieuw, nalezen
