    's.shrink.1': "این بوتل شیشه‌ای شکسته است. آن را از حساب می‌کشم.", // nieuw, nalezen
    's.shrink.2': "سودای خود را در صندوق یک همکار حساب می‌کنم.", // nieuw, nalezen
